Функция ПолучитьДебетовыйОборотПоКонтрагенту(Счет, Контрагент)
	Запрос = Новый Запрос;
	Запрос.Текст =
	"ВЫБРАТЬ
		SUMMA(Хозрасчетный.Сумма) КАК СуммаДт
	ИЗ
		РегистрБухгалтерии.Хозрасчетный КАК Хозрасчетный
	ГДЕ
		Хозрасчетный.СчетДт = &Счет
		И (Хозрасчетный.ДвиженияССубконто.СубконтоДт1 = &Контрагент
			ИЛИ Хозрасчетный.ДвиженияССубконто.СубконтоДт2 = &Контрагент)";

	Запрос.УстановитьПараметр("Счет", Счет);
	Запрос.УстановитьПараметр("Контрагент", Контрагент);

	Выборка = Запрос.Выполнить().Выбрать();
	Если НЕ Выборка.Следующий() Тогда
		Возврат 0;
	КонецЕсли;

	Если ЗначениеЗаполнено(Выборка.СуммаДт) Тогда
		Возврат Выборка.СуммаДт;
	Иначе
		Возврат 0;
	КонецЕсли;
КонецФункции
